const plan = $input.first().json;
if (plan.search_plan_version !== 2) throw new Error('Validation Failed: search_plan_version must be 2');
if (!plan.coverage_model) throw new Error('Validation Failed: Missing coverage_model');
if (!plan.coverage_model.strategy_group || typeof plan.coverage_model.strategy_group !== 'string') throw new Error('Validation Failed: Invalid strategy_group');
if (!plan.coverage_model.directive || typeof plan.coverage_model.directive !== 'string') throw new Error('Validation Failed: Invalid directive');
if (!plan.coverage_model.description || typeof plan.coverage_model.description !== 'string') throw new Error('Validation Failed: Invalid description');
if (!Array.isArray(plan.role_catalog) || plan.role_catalog.length === 0) throw new Error('Validation Failed: Empty role_catalog');
if (!Array.isArray(plan.location_catalog) || plan.location_catalog.length === 0) throw new Error('Validation Failed: Empty location_catalog');
const seenRoleIds = new Set();
const seenRoleTerms = new Set();
for (const r of plan.role_catalog) {
  if (!r.id || typeof r.id !== 'string') throw new Error(`Validation Failed: Role missing valid id`);
  if (seenRoleIds.has(r.id)) throw new Error(`Validation Failed: Duplicate role id ${r.id}`);
  seenRoleIds.add(r.id);
  if (!r.canonical || typeof r.canonical !== 'string' || r.canonical.trim().length === 0) throw new Error(`Validation Failed: Role ${r.id} missing canonical name`);
  const normCanonical = r.canonical.trim().toLowerCase();
  if (seenRoleTerms.has(normCanonical)) throw new Error(`Validation Failed: Duplicate canonical/alias role term ${r.canonical}`);
  seenRoleTerms.add(normCanonical);
  if (!r.family || typeof r.family !== 'string' || r.family.trim().length === 0) throw new Error(`Validation Failed: Role ${r.id} missing family`);
  if (![1, 2, 3].includes(r.priority)) throw new Error(`Validation Failed: Role ${r.id} has invalid priority, must be 1-3`);
  if (r.aliases) {
    if (!Array.isArray(r.aliases)) throw new Error(`Validation Failed: Role ${r.id} aliases must be array`);
    for (const a of r.aliases) {
      if (!a || typeof a !== 'string' || a.trim().length === 0) throw new Error(`Validation Failed: Role ${r.id} has invalid alias`);
      const normAlias = a.trim().toLowerCase();
      if (seenRoleTerms.has(normAlias)) throw new Error(`Validation Failed: Duplicate role alias across taxonomy: ${a}`);
      seenRoleTerms.add(normAlias);
    }
  }
}
const seenLocIds = new Set();
const seenLocTerms = new Set();
for (const l of plan.location_catalog) {
  if (!l.id || typeof l.id !== 'string') throw new Error(`Validation Failed: Location missing valid id`);
  if (seenLocIds.has(l.id)) throw new Error(`Validation Failed: Duplicate location id ${l.id}`);
  seenLocIds.add(l.id);
  if (!l.canonical || typeof l.canonical !== 'string' || l.canonical.trim().length === 0) throw new Error(`Validation Failed: Location ${l.id} missing canonical name`);
  const normCanonical = l.canonical.trim().toLowerCase();
  if (seenLocTerms.has(normCanonical)) throw new Error(`Validation Failed: Duplicate canonical/alias/area location ${l.canonical}`);
  seenLocTerms.add(normCanonical);
  if (![0, 1, 2].includes(l.tier)) throw new Error(`Validation Failed: Location ${l.id} has invalid tier, must be 0-2`);
  if (![1, 2, 3].includes(l.priority)) throw new Error(`Validation Failed: Location ${l.id} has invalid priority, must be 1-3`);
  if (l.aliases) {
    if (!Array.isArray(l.aliases)) throw new Error(`Validation Failed: Location ${l.id} aliases must be array`);
    for (const a of l.aliases) {
      if (!a || typeof a !== 'string' || a.trim().length === 0) throw new Error(`Validation Failed: Location ${l.id} has invalid alias`);
      const normAlias = a.trim().toLowerCase();
      if (seenLocTerms.has(normAlias)) throw new Error(`Validation Failed: Duplicate location alias across taxonomy: ${a}`);
      seenLocTerms.add(normAlias);
    }
  }
  if (l.related_areas) {
    if (!Array.isArray(l.related_areas)) throw new Error(`Validation Failed: Location ${l.id} related_areas must be array`);
    for (const ra of l.related_areas) {
      if (!ra || typeof ra !== 'string' || ra.trim().length === 0) throw new Error(`Validation Failed: Location ${l.id} has invalid related area`);
      const normRa = ra.trim().toLowerCase();
      if (seenLocTerms.has(normRa)) throw new Error(`Validation Failed: Duplicate location related_area across taxonomy: ${ra}`);
      seenLocTerms.add(normRa);
    }
  }
}
return { json: plan };
